// Plan 9 rc (Byron Rakitzis' rc) and es: '' doubling inside single quotes. One emitter, two spellings:
//   rc: if (c) { } else { }, while (c) { }, for (v in ..) { }, locals as `a=() { body }` (dynamic scope)
//   es: if {c} { } { }, while {c} { }, for (v = ..) { }, locals as `local (a=) { body }`; es has no
//       `continue`, so loop bodies catch a `continue` exception.
// Neither shell has arithmetic: integers go through expr(1). Strings are one-word lists; command
// substitution uses ``(){..} (rc) / ``''{..} (es) so output is not split.
#include "shell.hpp"
#include "emit_dialect.hpp"
#include <set>
namespace {
using namespace forge::script;
std::string rq(const std::string& s) { return forge::script::shellq::doubled(s, '\''); }
struct rc_dialect : block_dialect {
    bool es = false;
    std::vector<std::size_t> fn_line;                    // line index of the open fn header
    std::set<std::string> locals;                        // names local to the open fn
    std::string bq() const { return es ? "``''{" : "``(){"; }          // unsplit command substitution
    std::string bqs(const std::string& sep) const { return es ? "``" + rq(sep) + "{" : "``(" + rq(sep) + "){"; }
    std::string header() override {
        return "#!/usr/bin/env " + cx->exe + "\n# generated by `forge script --emit " + cx->target + "`; runs without FORGE\n";
    }
    std::string ident(const std::string& n) override {
        static const std::set<std::string> special = {"home", "path", "status", "prompt", "ifs", "pid", "apid", "cdpath", "history",
                                                      "bqstatus", "version", "noexport", "signals", "fn", "in", "if", "for", "while",
                                                      "switch", "not", "local", "let", "result", "return", "catch", "throw", "exit"};
        return special.count(n) ? n + "_" : n;
    }
    std::string s_lit(const std::string& s) override { return rq(s); }
    std::string ref(const std::string& n, ety, bool) override { return "$" + n; }
    std::string arith(char op, const std::string& a, const std::string& b) override {
        std::string o(1, op); if (op == '*') o = "'*'"; return "`{expr " + a + " " + o + " " + b + "}";
    }
    std::string neg(const std::string& a) override { return "`{expr 0 - " + a + "}"; }
    std::string concat(const std::vector<std::string>& p) override {
        std::string o; for (auto& x : p) { if (!o.empty()) o += "^"; o += x; } return o.empty() ? "''" : o;
    }
    std::string i2s(const std::string& i) override { return i; }
    std::string s2i(const std::string& s) override { return "`{expr " + s + " + 0}"; }
    std::string slen(const std::string& s) override { return "`{printf %s " + s + " | wc -c}"; }
    std::string cmp(const std::string& op, const std::string& a, const std::string& b, bool ints) override {
        static const std::pair<const char*, const char*> io[] = {{"==", "-eq"}, {"!=", "-ne"}, {"<", "-lt"}, {"<=", "-le"}, {">", "-gt"}, {">=", "-ge"}};
        if (ints) for (auto& [o, t] : io) if (op == o) return "test " + a + " " + t + " " + b;
        if (op == "==") return "test x^" + a + " '=' x^" + b;
        if (op == "!=") return "test x^" + a + " '!=' x^" + b;
        no("string ordering with " + op);
    }
    std::string c_and(const std::string& a, const std::string& b) override { return "{" + a + "} && {" + b + "}"; }
    std::string c_or(const std::string& a, const std::string& b) override { return "{" + a + "} || {" + b + "}"; }
    std::string c_not(const std::string& a) override { return "! {" + a + "}"; }
    std::string c_bool(bool v) override { return v ? "true" : "false"; }
    void let(const std::string& n, const std::string& v, ety, bool global, bool) override {
        if (cx->in_fn && !global) locals.insert(n);
        L(n + "=" + v);
        if (v.rfind("``", 0) == 0) L(es ? "if {~ $#" + n + " 0} {" + n + "=''}" : "if (~ $#" + n + " 0) " + n + "=''");
    }
    void print(const std::string& v, bool nl, bool err) override { L(std::string("printf '%s") + (nl ? "\\n" : "") + "' " + v + (err ? " >[1=2]" : "")); }
    std::string cond(const std::string& c) const { return es ? "{" + c + "}" : "(" + c + ")"; }
    void if_(const std::string& c) override { open("if " + cond(c) + " {"); }
    void else_() override { mid(es ? "} {" : "} else {"); }
    void end_if() override { close("}"); }
    std::string loop_open() const { return es ? " { catch @ _e _r {if {~ $_e continue} {} {throw $_e $_r}} {" : " {"; }
    std::string loop_close() const { return es ? "} }" : "}"; }
    void while_(const std::string& c) override { open("while " + cond(c) + loop_open()); }
    void end_while() override { close(loop_close()); }
    void for_(const std::string& v, const std::vector<std::string>& items) override {
        if (cx->in_fn) locals.insert(v);
        std::string s = "for (" + v + (es ? " =" : " in"); for (auto& i : items) s += " " + i; open(s + ")" + loop_open());
    }
    void end_for() override { close(loop_close()); }
    void brk() override { L("break"); }
    void cont() override { L(es ? "throw continue" : "continue"); }
    void fn_(const std::string& name, const std::vector<std::string>& ps) override {
        fn_line.push_back(cx->lines.size()); locals.clear();
        open("fn " + name + " {");
        for (std::size_t i = 0; i < ps.size(); ++i) { locals.insert(ps[i]); L(ps[i] + "=$" + (es ? "*(" + std::to_string(i + 1) + ")" : std::to_string(i + 1))); }
    }
    void end_fn() override {
        close("}");
        // Wrap the body in a dynamic-scope block binding every local (recursion-safe).
        std::string pre; for (auto& n : locals) pre += es ? (pre.empty() ? "" : "; ") + n + "=" : n + "=() ";
        auto& h = cx->lines[fn_line.back()]; fn_line.pop_back();
        h += es ? " local (" + pre + ") {" : " " + pre + "{";
        cx->lines.back() += " }";
        locals.clear();
    }
    void ret(const std::string& v) override { if (!v.empty()) L("_r=" + v); L("return 0"); }
    std::string call(const std::string& name, const std::vector<std::string>& a, bool want, ety rt) override {
        std::string s = name; for (auto& x : a) s += " " + x;
        L(s);
        if (!want) return "";
        auto t = cx->tmp(); let(t, "$_r", rt, !cx->in_fn, true); return ref(t, rt, !cx->in_fn);
    }
    void exit_(const std::string& c) override { L("exit " + c); }
    std::string env(const std::string& n, const std::string& d) override {
        std::string name; if (!lit_name(n, '\'', name)) no("a dynamic environment variable name");
        auto t = cx->tmp(); let(t, d, ety::Str, !cx->in_fn, true);
        if_("! ~ $#" + name + " 0"); let(t, "$^" + name, ety::Str, !cx->in_fn, false); end_if();
        return "$" + t;
    }
    void setenv(const std::string& n, const std::string& v) override { std::string name; if (!lit_name(n, '\'', name)) no("a dynamic environment variable name"); L(name + "=" + v); }
    std::string test_path(const std::string& p, char k) override { return std::string("test -") + k + " " + p; }
    void mkdir(const std::string& p) override { L("mkdir -p -- " + p); }
    void remove(const std::string& p) override { L("rm -rf -- " + p); }
    void write(const std::string& p, const std::string& s, bool app) override { L("printf '%s' " + s + (app ? " >> " : " > ") + p); }
    std::string read(const std::string& p) override { return bq() + "cat -- " + p + "}"; }
    std::string cwd() override { return bq() + "pwd -P | tr -d '\\n'}"; }
    std::string platform() override {
        return "`{sh -c " + rq("case $(uname -s) in Linux) if [ -n \"${ANDROID_ROOT-}\" ]; then echo android; else echo linux; fi;; Darwin) echo macos;; "
                              "FreeBSD) echo freebsd;; MINGW*|MSYS*|CYGWIN*|Windows_NT) echo windows;; *) echo other;; esac") + "}";
    }
    void run(const std::string& cmd, const std::string& o, const std::string& c, bool host) override {
        bool g = !cx->in_fn;
        auto t = cx->tmp(); if (cx->in_fn) locals.insert(t);
        std::string sep = "\x1c";
        if (host) L(t + "=" + bqs(sep) + (es ? "let (_s = <={eval " + cmd + "}) {printf '\\034%d' $_s}}" : "eval " + cmd + "; printf '\\034%d' $status}"));
        else L(t + "=" + bqs(sep) + "sh -c " + rq(sh_wrapper()) + " _ " + cmd + "}");
        if_("~ $#" + t + " 1"); let(o, "''", ety::Str, g, false); let(c, "$" + t + "(1)", ety::Int, g, false);
        else_(); let(o, "$" + t + "(1)", ety::Str, g, false); let(c, "$" + t + "(2)", ety::Int, g, false); end_if();
    }
    std::string sh_quote(const std::string& v) override {
        return "''''^" + bq() + "printf %s " + v + " | sed " + rq("s/'/'\"'\"'/g") + "}^''''";
    }
};
} // namespace
void forge_shell_register_rc(forge::script::shell_registry& r) {
    for (auto n : {"rc", "es"}) {
        forge::script::shell_backend b; b.name = n; b.exes = {n}; b.family = "rc";
        b.argv = forge::script::shellq::dash_c; b.quote = [](const std::string& s) { return forge::script::shellq::doubled(s, '\''); };
        bool is_es = std::string(n) == "es";
        b.emitter = [is_es] { auto d = std::make_unique<rc_dialect>(); d->es = is_es; return d; };
        b.emit_ext = is_es ? ".es" : ".rc"; b.emit_tested = true; b.golden_tested = true;
        r.add(std::move(b));
    }
}
